import { icon, brand, avatar } from './ui.js';
import { renderGroupDependents, renderDependentResults } from './dependents.js';

export const GROUP_ROUTES = ['dashboard', 'dashboard-empty', 'create-group', 'group', 'group-member', 'invite', 'invites-sent', 'draw-confirm', 'draw-running', 'drawn', 'reveal'];

const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const currency = value => Number(value || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2, maximumFractionDigits: 2 });
const dateLabel = value => { const date = value ? new Date(`${String(value).slice(0, 10)}T12:00:00`) : null; return date && !Number.isNaN(date.getTime()) ? date.toLocaleDateString('pt-BR', { day: 'numeric', month: 'long' }) : 'A combinar'; };
const accepted = state => (state.participants || []).filter(p => p.status === 'accepted');
const pending = state => (state.participants || []).filter(p => p.status !== 'accepted');
const back = (route = 'group', text = 'Voltar para o grupo') => `<a class="group-back" href="#${route}" data-route="${route}">${icon('arrow-left', 16)} ${text}</a>`;
const flower = () => `<div class="group-flower" aria-hidden="true"><i></i><i></i><i></i><i></i><b></b></div>`;
const giftArt = (className = '') => `<div class="group-gift-art ${className}" aria-hidden="true"><div class="group-gift-bow bow-left"></div><div class="group-gift-bow bow-right"></div><div class="group-gift-box"></div><div class="group-gift-lid"></div><div class="group-gift-ribbon"></div><span class="group-gift-spark spark-one">✧</span><span class="group-gift-spark spark-two">✦</span></div>`;
const pile = (people, max = 4) => `<div class="group-avatar-pile">${people.slice(0, max).map((p, i) => avatar(p.name, p.color ?? i, 'small', p.avatar ?? null)).join('')}${people.length > max ? `<span class="group-avatar-more">+${people.length - max}</span>` : ''}</div>`;

function dashboardInvitations(state) {
  const invitations = state.pendingInvitations || [];
  if (!invitations.length) return '';
  return `<section class="dashboard-invitations" aria-labelledby="dashboard-invitations-title"><div class="dashboard-section-heading dashboard-invitations-heading"><h2 id="dashboard-invitations-title">Convites para você <span>${invitations.length}</span></h2><span class="pill pill-orange">${invitations.length === 1 ? '1 convite pendente' : `${invitations.length} convites pendentes`}</span></div><p class="dashboard-invitations-intro">Recebidos por <strong>${escape(state.user?.email)}</strong>. Sua participação só começa quando você aceitar.</p><div class="dashboard-grid dashboard-invitations-grid">${invitations.map(invitation => {
    const group = invitation.group || {}, busy = state.acceptingInvitationId === group.id, error = state.dashboardInvitationErrors?.[group.id];
    return `<article class="dashboard-group-card dashboard-invitation-card"><div class="dashboard-card-top"><span class="dashboard-card-symbol family">${icon('mail', 23)}</span><span class="pill group-pill-neutral">Você foi convidado</span></div><h3>${escape(group.name)}</h3><p class="dashboard-invitation-organizer">Um convite de <strong>${escape(group.organizerName || 'quem organiza o grupo')}</strong></p><div class="dashboard-invitation-facts"><span>${icon('calendar', 16)} ${dateLabel(group.date)}</span><span>${icon('gift', 16)} ${currency(group.budget)}</span></div><div class="dashboard-invitation-actions"><button type="button" class="btn btn-primary btn-block" data-action="accept-dashboard-invite" data-group-id="${escape(group.id)}" ${state.acceptingInvitationId ? 'disabled' : ''} aria-busy="${busy}" aria-label="Aceitar convite para ${escape(group.name)}">${icon(busy ? 'clock' : 'check', 17)} ${busy ? 'Aceitando convite…' : 'Aceitar convite'}</button>${error ? `<p class="dashboard-invitation-error" role="alert">${escape(error)}</p>` : ''}</div></article>`;
  }).join('')}</div></section>`;
}

function dashboard(state, empty = false) {
  const people = accepted(state);
  const liveGroups = state.production ? (state.groups || []) : null;
  const hasInvitations = Boolean(state.pendingInvitations?.length);
  if (liveGroups) empty = liveGroups.length === 0;
  const liveCards = liveGroups?.map(group => {
    const members = group.participants || [];
    const count = Number(group.acceptedCount ?? group.participantCount ?? 0);
    const drawn = Boolean(group.drawn || group.drawnAt);
    return `<a class="dashboard-group-card" href="#group?id=${encodeURIComponent(group.id)}" data-route="group" data-group-id="${escape(group.id)}"><div class="dashboard-card-top"><span class="dashboard-card-symbol family">${icon('gift', 25)}</span><span class="pill ${drawn ? 'pill-green' : 'pill-orange'}">${drawn ? 'Sorteio realizado' : 'Preparando a surpresa'}</span></div><h3>${escape(group.name)}</h3><p>${icon('calendar', 15)} ${dateLabel(group.date)} <span>·</span> ${currency(group.budget)}</p><div class="dashboard-card-bottom"><div>${members.length ? pile(members) : ''}<span>${count} ${count === 1 ? 'participante confirmado' : 'participantes confirmados'}</span></div><span class="dashboard-card-arrow">${icon('arrow-right', 20)}</span></div></a>`;
  }).join('');
  return `<section class="dashboard-page">
    <div class="dashboard-greeting"><span class="eyebrow">SEU CANTINHO DE ENCONTROS</span><p>Olá, ${escape(state.user?.firstName || (state.production ? 'pessoa querida' : 'Fábio'))}. Que bom ter você por aqui ${icon('sparkles', 16)}</p></div>
    <div class="dashboard-title-row"><h1>Toda boa surpresa<br> começa com um grupo<span>.</span></h1><button class="btn btn-primary" data-route="create-group">${icon('plus', 18)} Criar um grupo</button></div>
    ${state.production ? `<div class="dashboard-secondary-actions"><button type="button" class="btn btn-secondary" data-route="dependents">${icon('users', 17)} Meus dependentes ${icon('arrow-right', 15)}</button></div>` : ''}
    ${dashboardInvitations(state)}
    <div class="dashboard-feature"><div class="dashboard-feature-copy"><span class="dashboard-feature-kicker">MENOS ORGANIZAÇÃO. MAIS CONEXÃO.</span><h2>A melhor parte do presente<br> é quem está do outro lado.</h2><p>Reúna suas pessoas favoritas.<br> A gente cuida de guardar a surpresa.</p></div>${giftArt()}<span class="dashboard-feature-dot dot-one"></span><span class="dashboard-feature-dot dot-two"></span></div>
    <div class="dashboard-section-heading"><h2>Seus grupos <span>${empty ? 0 : liveGroups ? liveGroups.length : 2}</span></h2><span class="muted">Pequenos rituais, boas memórias.</span></div>
    ${empty && hasInvitations ? `<div class="dashboard-awaiting-group panel"><span class="group-icon-circle">${icon('users', 23)}</span><div><h2>Seu próximo encontro está aqui.</h2><p>Aceite um convite acima para que o grupo apareça nesta lista.</p></div></div>` : empty ? `<div class="dashboard-empty panel"><div class="group-icon-circle">${icon('users', 28)}</div><h2>A turma ainda vai chegar.</h2><p>Crie seu primeiro grupo e convide quem<br> vai fazer parte dessa surpresa.</p><button class="btn btn-primary" data-route="create-group">${icon('plus', 18)} Criar meu primeiro grupo</button><div class="dashboard-empty-note">Um grupo, alguns amigos e muito carinho.</div></div>` : `<div class="dashboard-grid">
      ${liveGroups ? liveCards : `<a class="dashboard-group-card" href="#group" data-route="group"><div class="dashboard-card-top"><span class="dashboard-card-symbol family">${icon('gift', 25)}</span><span class="pill ${state.drawn ? 'pill-green' : 'pill-orange'}">${state.drawn ? 'Sorteio realizado' : 'Preparando a surpresa'}</span></div><h3>${escape(state.group?.name || 'Natal da família')}</h3><p>${icon('calendar', 15)} ${dateLabel(state.group?.date)} <span>·</span> ${currency(state.group?.budget)}</p><div class="dashboard-card-bottom"><div>${pile(people)}<span>${people.length} participantes confirmados</span></div><span class="dashboard-card-arrow">${icon('arrow-right', 20)}</span></div></a>
      <article class="dashboard-group-card dashboard-demo-card"><div class="dashboard-card-top"><span class="dashboard-card-symbol company">${icon('users', 25)}</span><span class="pill group-pill-neutral">Em breve</span></div><h3>Amigo da firma</h3><p>${icon('calendar', 15)} Uma nova tradição vem aí</p><div class="dashboard-card-bottom"><div><span class="dashboard-small-label">IDEIA PARA O PRÓXIMO ENCONTRO</span><span>Até o café fica mais divertido.</span></div><span class="dashboard-card-sprig" aria-hidden="true">✳</span></div></article>`}
      <button class="dashboard-new-card" data-route="create-group"><span>${icon('plus', 25)}</span><h3>Tem mais gente querida?</h3><p>Crie outro grupo e espalhe<br> a surpresa por aí.</p><b>Criar novo grupo ${icon('arrow-right', 16)}</b></button>
    </div>`}
    <div class="dashboard-bottom-note">${icon('heart', 15)} Feito para aproximar. Criado para surpreender.</div>
  </section>`;
}

function createGroup(state) {
  return `<section class="group-create-page">${back('dashboard', 'Meus grupos')}<div class="group-page-intro"><span class="eyebrow">O COMEÇO DE UMA BOA HISTÓRIA</span><h1>Vamos reunir a turma?</h1><p>Defina os detalhes do encontro. O carinho fica por conta de vocês.</p></div>
    <div class="group-create-layout"><form class="panel group-create-form" data-form="create-group"><div class="group-section-label"><span>01</span><h2>Um encontro com a sua cara</h2></div>
      <label class="field">Nome do grupo <input name="name" required maxlength="80" placeholder="Ex.: Natal da família" autocomplete="off"><span>Um nome que todo mundo vai reconhecer.</span></label>
      <div class="group-form-row"><div class="field group-date-field" data-date-field><label id="group-date-label">Data da troca</label><input type="hidden" name="date" value="${state.production ? '' : '2026-12-24'}"><button type="button" class="group-date-trigger" data-date-trigger aria-haspopup="dialog" aria-expanded="false" aria-controls="group-calendar" aria-describedby="group-date-error"><span data-date-value>Escolha uma data</span>${icon('calendar', 18)}</button><span id="group-date-error" class="group-date-error" data-date-error role="alert"></span><dialog id="group-calendar" class="group-calendar" data-calendar-dialog aria-labelledby="group-calendar-title"></dialog></div><label class="field">Valor sugerido do presente <div class="group-currency-input"><span>R$</span><input type="text" name="budget" data-budget-input inputmode="decimal" autocomplete="off" maxlength="12" value="100,00" required aria-label="Valor sugerido do presente em reais" aria-describedby="group-budget-hint group-budget-error"></div><span id="group-budget-hint" class="group-budget-hint">A partir de R$ 1,00.</span><span id="group-budget-error" class="group-budget-error" data-budget-error role="alert"></span></label></div>
      <label class="field">Onde vai acontecer? <span class="group-optional">opcional</span><input name="location" maxlength="120" placeholder="Ex.: Casa da vó Lúcia" autocomplete="off"></label>
      <label class="field">Um recadinho para o grupo <span class="group-optional">opcional</span><textarea name="description" rows="3" maxlength="500" placeholder="Conte um pouco sobre esse encontro..."></textarea></label>
      <div class="group-form-footer"><a href="#dashboard" data-route="dashboard">Cancelar</a><button class="btn btn-primary" type="submit">Criar grupo ${icon('arrow-right', 18)}</button></div>
    </form><aside class="group-create-aside"><div class="group-aside-illustration">${giftArt('group-gift-small')}</div><span class="eyebrow">CADA DETALHE FAZ DIFERENÇA</span><h2>O presente começa<br> no encontro.</h2><p>Um valor combinado, um lugar especial e as pessoas certas. O resto é surpresa.</p><ul><li>${icon('check', 17)} Você pode convidar por e-mail.</li><li>${icon('check', 17)} Cada pessoa vê só o próprio resultado.</li><li>${icon('check', 17)} Ninguém tira a si mesmo.</li></ul><div class="group-aside-tip">${icon('heart', 18)} O melhor presente é estar junto.</div></aside></div></section>`;
}

const statuses = {
  accepted: { text: 'Participando', className: 'green', glyph: 'check-circle', detail: 'Convite aceito' },
  opened: { text: 'Abertura estimada', className: 'blue', glyph: 'eye', detail: 'Sinal de abertura detectado' },
  delivered: { text: 'Entregue', className: 'neutral', glyph: 'check', detail: 'No servidor de destino' },
  sent: { text: 'Enviado', className: 'neutral', glyph: 'send', detail: 'Aguardando entrega' },
  failed: { text: 'Falha no envio', className: 'red', glyph: 'alert', detail: 'Confira o endereço de e-mail' },
};

function participantRow(person, index, state) {
  const status = statuses[person.status] || statuses.sent;
  const isDependent = Boolean(person.isDependent || person.dependentId);
  const isMe = !isDependent && person.email === state.user?.email;
  const isMember = state.role === 'member';
  const organizerEmail = state.organizerEmail || (isMember ? (state.production ? '' : 'ana@exemplo.com') : state.user?.email);
  const isOrganizer = !isDependent && (person.isOrganizer || Boolean(organizerEmail && person.email === organizerEmail));
  const rowAction = isDependent ? `<span class="group-role">${person.guardianId === state.user?.id ? 'Seu dependente' : 'Dependente'}</span>` : isOrganizer ? '<span class="group-role">Organizador</span>'
    : person.status === 'accepted' ? `<span class="group-role">${isMe ? 'Você' : 'Confirmado'}</span>`
    : isMember || state.drawn ? '<span class="group-role">Convidado</span>'
    : `<button class="group-text-button" data-action="resend-invite" data-email="${escape(person.email)}">${icon('refresh', 14)} Reenviar</button>`;
  return `<tr><td><div class="group-person">${avatar(person.name, person.color ?? index, 'small', person.avatar ?? null)}<div><strong>${escape(person.name)} ${isMe ? '<small>você</small>' : ''}${isDependent ? '<span class="dependent-person-tag">Dependente</span>' : ''}</strong><span>${isDependent ? `Responsável: ${escape(person.responsibleName || 'uma pessoa do grupo')}` : escape(person.email)}</span></div></div></td><td><span class="group-status group-status-${status.className}" ${person.status === 'opened' ? 'title="Abertura estimada: sinais automáticos do e-mail não garantem que a mensagem foi lida."' : ''}>${icon(status.glyph, 13)} ${status.text}${person.status === 'opened' ? icon('info', 12) : ''}</span></td><td class="group-person-action">${rowAction}</td></tr>`;
}

function groupPage(state) {
  const people = state.participants || [], confirmed = accepted(state), waiting = pending(state), failed = people.filter(p => p.status === 'failed').length;
  const isMember = state.role === 'member';
  const organizerEmail = state.organizerEmail || (isMember ? (state.production ? '' : 'ana@exemplo.com') : state.user?.email);
  const organizerName = state.group?.organizerName?.split(' ')[0] || people.find(person => person.email === organizerEmail)?.name?.split(' ')[0] || (state.production ? 'quem organiza o grupo' : 'Ana');
  const memberSidebar = `<div class="panel group-next-card group-member-card"><span class="group-member-check">${icon(state.drawn ? 'gift' : 'check', 25)}</span><span class="eyebrow">VOCÊ FAZ PARTE</span><h2>${state.drawn ? 'Sua surpresa está pronta.' : 'Sua participação está confirmada.'}</h2><p>${state.drawn ? 'Chegou a hora de descobrir quem vai receber seu carinho.' : `Agora é só aguardar ${escape(organizerName)} fazer o sorteio. Vamos avisar por e-mail quando seu amigo secreto estiver definido.`}</p><div class="group-member-summary">${icon('users', 17)} <span><strong>${confirmed.length} pessoas</strong> já confirmaram presença.</span></div>${state.drawn ? `<button class="btn btn-primary" data-route="reveal">${icon('gift', 17)} ${state.revealed ? 'Ver meu amigo secreto' : 'Descobrir meu amigo'}</button><small>Consulte seu resultado na sua conta.</small>` : `<div class="group-member-waiting">${icon('clock', 16)} Aguardando o sorteio</div>`}</div>`;
  return `<section class="group-detail-page">${back('dashboard', 'Meus grupos')}<div class="group-detail-title"><div><span class="eyebrow">GENTE QUERIDA, PRESENTE CERTO</span><h1>${escape(state.group?.name)}</h1><p>${escape(state.group?.description || 'Um encontro para criar novas memórias.')}</p></div><span class="pill ${state.drawn ? 'pill-green' : 'pill-orange'}">${icon(state.drawn ? 'check-circle' : 'clock', 14)} ${state.drawn ? 'Sorteio realizado' : 'Aguardando sorteio'}</span></div>
    <div class="group-event-strip"><div>${icon('calendar', 21)}<span>DATA DA TROCA<strong>${dateLabel(state.group?.date)}</strong></span></div><div>${icon('gift', 21)}<span>VALOR SUGERIDO<strong>${currency(state.group?.budget)}</strong></span></div><div>${icon('heart', 21)}<span>NOSSO PONTO DE ENCONTRO<strong>${escape(state.group?.location || 'A combinar')}</strong></span></div><span class="group-event-art" aria-hidden="true">✳</span></div>
    ${state.production && !isMember && state.group?.notificationFailures ? `<div class="inline-notice" role="status">${icon('mail', 20)}<div><strong>Alguns avisos por e-mail não foram enviados.</strong><p>${state.drawn ? 'O sorteio está salvo e os resultados já podem ser consultados na conta.' : 'Seu grupo está salvo. Você pode acompanhar os envios e tentar novamente por aqui.'}</p><button class="btn btn-secondary" data-action="retry-notifications">Tentar enviar novamente ${icon('refresh', 16)}</button></div></div>` : ''}
    ${state.drawn ? `<div class="group-drawn-banner"><span class="group-icon-circle">${icon('sparkles', 22)}</span><div><strong>A surpresa já tem destino.</strong><p>O sorteio foi realizado. Cada participante pode descobrir seu amigo secreto.</p></div><button class="btn btn-primary" data-route="reveal">${state.revealed ? 'Ver meu amigo secreto' : 'Descobrir meu amigo'} ${icon('arrow-right', 16)}</button></div>` : ''}
    <div class="group-detail-grid"><div class="group-participants-panel panel"><div class="group-participants-heading"><div><h2>A turma <span>${people.length}</span></h2><p>Quem vai fazer parte dessa história.</p></div>${!state.drawn && !isMember ? `<button class="btn btn-secondary group-invite-button" data-route="invite">${icon('plus', 17)} Convidar pessoas</button>` : ''}</div><div class="group-table-tabs"><span class="group-active-tab">${icon('users', 17)} Participantes</span>${state.production ? `<button type="button" class="group-text-button" data-action="refresh-group">${icon('refresh', 15)} Atualizar lista</button>` : !isMember ? `<a href="#email-invite" data-route="email-invite">${icon('mail', 16)} Prévia do convite ${icon('arrow-right', 14)}</a>` : ''}</div><div class="group-table-wrap"><table class="group-participants-table"><thead><tr><th>PARTICIPANTE</th><th>STATUS DO CONVITE</th><th><span class="group-sr-only">Ações</span></th></tr></thead><tbody>${people.map((p, i) => participantRow(p, i, state)).join('')}</tbody></table>${people.length === 0 ? '<div class="group-no-participants">A turma está se formando. Envie o primeiro convite!</div>' : ''}</div><div class="group-table-footnote">${icon('info', 14)} A abertura do e-mail é estimada e não confirma a leitura.</div></div>
    <aside class="group-sidebar">${isMember ? memberSidebar : `<div class="panel group-next-card"><span class="eyebrow">${state.drawn ? 'SURPRESA A CAMINHO' : 'TUDO NO SEU TEMPO'}</span><h2>${state.drawn ? 'Agora é com vocês.' : 'Quase na hora<br> da surpresa.'}</h2><p>${state.drawn ? 'O sorteio está pronto. Prepare um presente com a cara de quem você tirou.' : 'A turma está se formando. Acompanhe as confirmações por aqui.'}</p><div class="group-confirm-count"><strong>${confirmed.length}</strong><span>de ${people.length} pessoas<br> confirmadas</span><div class="group-progress-ring" style="--group-progress:${people.length ? Math.round(confirmed.length / people.length * 100) : 0}%">${icon('users', 20)}</div></div><div class="group-progress-bar"><span style="width:${people.length ? Math.round(confirmed.length / people.length * 100) : 0}%"></span></div><div class="group-side-facts"><div><span>${icon('check-circle', 15)} Participando</span><strong>${confirmed.length}</strong></div><div><span>${icon('clock', 15)} Aguardando resposta</span><strong>${waiting.length - failed}</strong></div>${failed ? `<div class="group-failed-fact"><span>${icon('alert', 15)} Falha no envio</span><strong>${failed}</strong></div>` : ''}</div><button class="btn btn-primary" data-route="${state.drawn ? 'reveal' : 'draw-confirm'}">${icon(state.drawn ? 'gift' : 'sparkles', 17)} ${state.drawn ? 'Ver meu amigo secreto' : 'Fazer o sorteio'}</button><small>${state.drawn ? 'Consulte seu resultado na sua conta.' : 'O sorteio inclui apenas quem confirmou.'}</small></div>`}<div class="group-privacy-note">${icon('lock', 20)}<div><strong>O segredo fica entre vocês.</strong><p>Os resultados não aparecem na lista de participantes.</p></div></div></aside></div>${renderGroupDependents(state)}${state.production && state.role === 'organizer' ? `<div class="group-delete-area"><div><strong>Encerrar este encontro</strong><p>Apague o grupo e seus dados quando não precisar mais deles.</p></div><button class="btn btn-danger-outline" data-action="delete-group">${icon('x', 17)} Apagar amigo secreto</button></div>` : ''}</section>`;
}

function invitePage(state) {
  return `<section class="invite-page">${back()}<div class="group-page-intro"><span class="eyebrow">CABEM MAIS PESSOAS NESSA HISTÓRIA</span><h1>Chame quem faz parte.</h1><p>Um convite é o primeiro carinho. Quem você quer por perto?</p></div><div class="invite-layout"><form class="panel invite-form invite-repeater-form" data-form="invite" data-invite-fields><div class="invite-form-heading"><span class="group-icon-circle">${icon('mail', 23)}</span><div><h2>Convidar por e-mail</h2><p>Um endereço para cada pessoa da sua turma.</p></div></div><p class="invite-fields-intro" id="invite-email-help">Preencha todos os campos adicionados. Você pode enviar até 50 convites de uma vez.</p><div class="invite-email-list" data-invite-list><div class="invite-email-row" data-invite-row><label class="invite-email-field" for="invite-email-1"><span data-invite-label>E-mail do convidado 1</span><input id="invite-email-1" name="emails" type="email" inputmode="email" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="254" pattern="[^ @]+@[^ @]+[.][^ @]+" required placeholder="nome@exemplo.com" aria-describedby="invite-email-help"></label><button class="invite-remove-email" type="button" data-invite-remove aria-label="Remover e-mail do convidado 1" title="Mantenha pelo menos um e-mail" disabled>${icon('x', 15)}<span>Remover</span></button></div></div><div class="invite-add-row"><button class="btn btn-secondary invite-add-email" type="button" data-invite-add>${icon('plus', 17)} Adicionar e-mail</button><span class="invite-field-count" data-invite-count>1 de 50</span></div><p class="invite-fields-status" data-invite-status role="status" aria-live="polite"></p><div class="invite-help">${icon('info', 17)}<p>Cada pessoa recebe um convite individual. E-mails repetidos ou já convidados são considerados uma única vez.</p></div><div class="group-form-footer"><a href="#group" data-route="group">Agora não</a><button class="btn btn-primary" type="submit">${icon('send', 17)} Enviar convites</button></div></form><aside class="invite-send-summary" aria-label="Resumo do grupo e próximos passos"><div class="invite-summary-top"><span class="invite-summary-symbol">${icon('gift', 28)}</span><span class="eyebrow">SUA PRÓXIMA BOA SURPRESA</span><h2>${escape(state.group?.name)}</h2><p>A turma começa a se reunir por aqui.</p></div><div class="invite-summary-details"><div>${icon('calendar', 18)}<span>Data da troca<strong>${dateLabel(state.group?.date)}</strong></span></div><div>${icon('gift', 18)}<span>Valor do presente<strong>${currency(state.group?.budget)}</strong></span></div><div>${icon('map-pin', 18)}<span>Nosso encontro<strong>${escape(state.group?.location || 'A combinar')}</strong></span></div></div><div class="invite-summary-next"><h3>Depois de enviar</h3><ol><li><span>01</span><p>O convite chega ao e-mail de cada pessoa.</p></li><li><span>02</span><p>Cada pessoa aceita o convite pelo e-mail ou no painel.</p></li><li><span>03</span><p>Você acompanha os envios e as confirmações no grupo.</p></li></ol></div><div class="invite-summary-secret">${icon('lock', 17)}<p>O sorteio inclui apenas quem confirmou. O segredo fica bem guardado.</p></div></aside></div></section>`;
}

function invitesSent(state) {
  const emails = state.inviteEmails || [];
  return `<section class="invite-sent-page"><div class="invite-sent-card panel"><span class="group-success-mark">${icon('check', 31)}</span><span class="eyebrow">O PRIMEIRO PASSO ESTÁ DADO</span><h1>Convites a caminho<span>!</span></h1><p>${emails.length ? `Você convidou ${emails.length} ${emails.length === 1 ? 'pessoa' : 'pessoas'} para` : 'Seus convidados já podem fazer parte de'}<br><strong>${escape(state.group?.name)}</strong>.</p>${emails.length ? `<div class="invite-sent-list">${emails.map(email => `<div>${icon('mail', 17)}<span>${escape(email)}</span><span class="group-status group-status-${state.production && state.inviteQueued?.includes(email) ? 'neutral' : 'sent'}">${state.production && state.inviteQueued?.includes(email) ? 'Na fila' : 'Enviado'}</span></div>`).join('')}</div>` : ''}<div class="invite-sent-info">${icon('clock', 19)}<p>Agora é esperar a turma chegar. Você pode acompanhar cada confirmação na página do grupo.</p></div><button class="btn btn-primary" data-route="group">Acompanhar meu grupo ${icon('arrow-right', 18)}</button><button class="btn btn-ghost" data-route="invite">Convidar mais pessoas</button></div></section>`;
}

function drawConfirm(state) {
  const people = accepted(state), waiting = pending(state), canDraw = people.length >= 3;
  return `<section class="draw-confirm-page">${back()}<div class="draw-confirm-layout"><div class="draw-confirm-story"><span class="eyebrow">UM CLIQUE. MUITAS POSSIBILIDADES.</span><h1>Vamos dar destino<br> a essa surpresa?</h1><p>Daqui a pouco, cada pessoa terá<br> alguém especial para presentear.</p>${giftArt('draw-story-gift')}<div class="draw-story-note">${icon('lock', 17)} Participantes e responsáveis consultam seus resultados.</div></div><div class="panel draw-confirm-card"><div class="draw-card-heading"><span class="group-icon-circle">${icon('sparkles', 24)}</span><div><h2>Está quase na hora.</h2><p>${escape(state.group?.name)}</p></div></div><div class="draw-participant-summary"><div><strong>${people.length} participantes confirmados</strong><span>São essas pessoas que entram no sorteio.</span></div>${pile(people, 6)}</div><div class="draw-confirm-names">${people.map((p, i) => `<span>${avatar(p.name, p.color ?? i, 'small', p.avatar ?? null)}${escape(p.name.split(' ')[0])}</span>`).join('')}</div>${waiting.length ? `<div class="draw-warning">${icon('info', 20)}<div><strong>${waiting.length} ${waiting.length === 1 ? 'pessoa ainda não confirmou' : 'pessoas ainda não confirmaram'}</strong><p>${waiting.map(p => escape(p.name.split(' ')[0])).join(', ')} ${waiting.length === 1 ? 'ficará de fora' : 'ficarão de fora'} deste sorteio. Você pode voltar e esperar ou continuar só com os confirmados.</p></div></div>` : ''}${!canDraw ? `<div class="draw-blocked" role="alert">${icon('alert', 20)}<div><strong>Falta um pouquinho para começar.</strong><p>Precisamos de pelo menos 3 participantes confirmados. Convide mais pessoas ou aguarde as confirmações.</p></div></div>` : ''}<div class="draw-rules"><div>${icon('check', 16)} Ninguém tira a si mesmo.</div><div>${icon('check', 16)} Todos dão e recebem um presente.</div><div>${icon('check', 16)} Uma única corrente conecta todo o grupo.</div></div>${canDraw ? `<label class="draw-consent"><input type="checkbox" name="drawConsent" required><span>Conferi a lista e entendo que apenas os <strong>${people.length} confirmados</strong> participarão. O resultado não poderá ser alterado.</span></label><button class="btn btn-primary draw-submit" data-action="run-draw">${icon('sparkles', 18)} Sim, fazer o sorteio</button>` : `<button class="btn btn-primary draw-submit" data-route="invite">${icon('plus', 18)} Convidar mais pessoas</button>`}<a href="#group" class="draw-back-link" data-route="group">Voltar para o grupo</a></div></div></section>`;
}

function drawRunning(state) {
  return `<section class="draw-running-page" aria-live="polite"><div class="draw-running-orbit"><span class="draw-orbit dot-a"></span><span class="draw-orbit dot-b"></span><span class="draw-orbit dot-c"></span><div class="draw-running-gift">${icon('gift', 50)}</div></div><span class="eyebrow">DEIXA A SURPRESA COM A GENTE</span><h1>Conectando<br> pessoas queridas<span>...</span></h1><p>Estamos sorteando ${escape(state.group?.name)}.<br> Cada presente está encontrando seu destino.</p><div class="draw-loading-line"><span></span></div><small>${icon('lock', 14)} Tudo acontece em segredo.</small></section>`;
}

function drawnPage(state) {
  return `<section class="draw-done-page"><div class="draw-done-card panel"><div class="draw-done-illustration">${flower()}<span class="draw-confetti confetti-one">✧</span><span class="draw-confetti confetti-two">✦</span><span class="draw-confetti confetti-three">·</span></div><span class="eyebrow">CADA SURPRESA ENCONTROU SEU DESTINO</span><h1>Está sorteado<span>!</span></h1><p>A corrente de carinho de <strong>${escape(state.group?.name)}</strong><br> está pronta. Agora vem a melhor parte.</p><div class="draw-done-stats"><div>${icon('users', 20)}<strong>${accepted(state).length}</strong><span>pessoas conectadas</span></div><span></span><div>${icon('gift', 20)}<strong>${accepted(state).length}</strong><span>surpresas a caminho</span></div></div><p class="draw-done-email">${icon('mail', 17)} Os resultados chegam por e-mail<br> aos participantes e responsáveis.</p><button class="btn btn-primary" data-route="reveal">Descobrir meu amigo secreto ${icon('arrow-right', 18)}</button><a class="draw-back-link" href="#group" data-route="group">Voltar para o grupo</a><div class="draw-done-private">${icon('shield', 17)} Os resultados ficam nas contas dos participantes e responsáveis.</div></div></section>`;
}

function revealPage(state) {
  if (state.production && !state.match?.name) state = { ...state, revealed: false };
  const hasDependents = Boolean(state.ownDependents?.some(dependent => dependent.active));
  const dependentMatch = Boolean(state.match?.isDependent || state.match?.dependentId);
  return `<section class="draw-reveal-page">${back()}<div class="draw-reveal-heading"><span class="eyebrow">${escape(state.group?.name || 'UM PRESENTE COM DESTINO')}</span><h1>${state.revealed ? 'Agora, guarde esse segredo.' : 'Tem alguém esperando\nseu carinho.'}</h1><p>${state.revealed ? 'Pense no que faz essa pessoa sorrir. É um ótimo começo.' : hasDependents ? 'Seu resultado e o dos seus dependentes estão aqui. Vamos descobrir?' : 'Um nome, muitas ideias. Pronto para descobrir?'}</p></div><div class="draw-reveal-card ${state.revealed ? 'is-revealed' : ''}"><div class="draw-reveal-corner" aria-hidden="true">✧</div>${state.revealed ? `<span class="draw-match-label">SEU AMIGO SECRETO É</span><div class="draw-match-avatar">${avatar(state.match?.name || (state.production ? 'Seu amigo secreto' : 'Ana Oliveira'), 2, 'large', state.match?.avatar ?? null)}<span>${icon('heart', 17)}</span></div><h2>${escape(state.match?.name || (state.production ? 'Seu amigo secreto' : 'Ana Oliveira'))}</h2><p class="dependent-match-contact">${dependentMatch ? `Dependente · responsável: ${escape(state.match?.responsibleName || 'uma pessoa do grupo')}` : escape(state.match?.email || (state.production ? '' : 'ana@exemplo.com'))}</p><div class="draw-match-divider"></div><div class="draw-match-details"><span>${icon('calendar', 17)} ${dateLabel(state.group?.date)}</span><span>${icon('gift', 17)} ${currency(state.group?.budget)}</span></div><span class="draw-match-note">Que seja um presente cheio de significado.</span>` : `<span class="draw-match-label">${hasDependents ? 'AS SURPRESAS DA SUA TURMA' : 'UMA SURPRESA SÓ SUA'}</span>${giftArt('draw-reveal-gift')}<h2>O segredo está aqui.</h2><p>Abra com calma.<br> ${hasDependents ? 'Você também acompanha os resultados dos seus dependentes.' : 'Essa parte é só entre nós.'}</p><button class="btn btn-primary" data-action="reveal">${icon('gift', 18)} ${hasDependents ? 'Revelar nossos amigos secretos' : 'Revelar meu amigo secreto'}</button>`}</div>${renderDependentResults(state)}<div class="draw-reveal-privacy">${icon('lock', 16)} ${hasDependents ? 'Você consulta seu resultado e os dos dependentes sob sua responsabilidade.' : state.revealed ? 'Cada participante consulta seu próprio resultado.' : 'Consulte seu resultado na sua conta.'}</div>${state.revealed ? `<div class="draw-result-actions"><button class="btn btn-secondary" data-action="hide-result">${icon('lock', 17)} Guardar resultados</button><button class="btn btn-secondary" data-route="group">Voltar para o grupo ${icon('arrow-right', 17)}</button></div>` : ''}</section>`;
}

export function renderGroups(route, state) {
  if (!GROUP_ROUTES.includes(route)) return null;
  switch (route) {
    case 'dashboard': return dashboard(state);
    case 'dashboard-empty': return dashboard(state, true);
    case 'create-group': return createGroup(state);
    case 'group': return groupPage(state);
    case 'group-member': return groupPage({ ...state, role: 'member' });
    case 'invite': return invitePage(state);
    case 'invites-sent': return invitesSent(state);
    case 'draw-confirm': return drawConfirm(state);
    case 'draw-running': return drawRunning(state);
    case 'drawn': return drawnPage(state);
    case 'reveal': return revealPage(state);
    default: return null;
  }
}
